import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const m=JSON.parse('{"title":"开发、发布与运行","description":"分清工程、开发环境、预览、版本和部署，以及组织账号与工程用户的用途。","frontmatter":{"title":"开发、发布与运行","description":"分清工程、开发环境、预览、版本和部署，以及组织账号与工程用户的用途。","status":"reviewed","kind":"explanation"},"headers":[],"relativePath":"zh/concepts/development-and-runtime.md","filePath":"zh/核心概念/开发、发布与运行.md"}'),o={name:"zh/concepts/development-and-runtime.md"};function n(h,t,i,l,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="开发、发布与运行" tabindex="-1">开发、发布与运行 <a class="header-anchor" href="#开发、发布与运行" aria-label="Permalink to &quot;开发、发布与运行&quot;">​</a></h1><p>基础名词先看<a href="/induframe-docs/zh/concepts/getting-oriented.html">名词入门</a>，环境和实际服务器的关系见<a href="/induframe-docs/zh/concepts/environments-and-nodes.html">运行环境与节点</a>。</p><p>看到工程、打开工作区和正式运行应用，是不同的步骤。先分清它们，就不容易把“已经创建”误当作“已经上线”。</p><h2 id="从工程到正式使用" tabindex="-1">从工程到正式使用 <a class="header-anchor" href="#从工程到正式使用" aria-label="Permalink to &quot;从工程到正式使用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>可以怎样理解</th></tr></thead><tbody><tr><td>工程</td><td>管理应用源码、数据配置和相关资料的容器</td></tr><tr><td>应用开发工作区</td><td>用 AI、编辑器和其他工具维护工程的地方</td></tr><tr><td>开发预览</td><td>查看当前开发页面、检查交互和数据的入口</td></tr><tr><td>工程版本</td><td>把工程内容整理成可部署、可识别的版本</td></tr><tr><td>部署</td><td>选择运行环境和相应条件，让工程在目标位置运行</td></tr></tbody></table><p>新建工程后，还需要准备初始源码。预览正常后，若要正式使用，继续核对数据配置、权限、版本和部署条件。</p><p>正式运行使用已部署版本，不依赖你一直开着开发工作区。只修改开发源码或上传开发资料，不会自动替换已部署的正式版本。</p><h2 id="三种状态不要混淆" tabindex="-1">三种状态不要混淆 <a class="header-anchor" href="#三种状态不要混淆" aria-label="Permalink to &quot;三种状态不要混淆&quot;">​</a></h2><ul><li><strong>工程已创建</strong>：工程记录存在，不一定已经初始化源码。</li><li><strong>开发环境已启动</strong>：开发工具准备好，不等于工程已部署。</li><li><strong>部署显示运行中</strong>：目标部署在运行，仍需检查实际页面和业务结果。</li></ul><p>“开发环境已停止”也不等于删除工程；“工程未部署”也不等于开发工作区不可用。</p><h2 id="公开工程-不等于公开网站" tabindex="-1">“公开工程”不等于公开网站 <a class="header-anchor" href="#公开工程-不等于公开网站" aria-label="Permalink to &quot;“公开工程”不等于公开网站&quot;">​</a></h2><p>工程可见范围中的“公开”，用于同组织成员按权限协作，仍需要登录。它不同于把一个应用发布到互联网。</p><p>向他人提供资源地址、开发预览地址或截图，也不会自动给对方账号授权。实际对外运行地址由部署和访问设置决定。</p><h2 id="组织账号和工程用户不同" tabindex="-1">组织账号和工程用户不同 <a class="header-anchor" href="#组织账号和工程用户不同" aria-label="Permalink to &quot;组织账号和工程用户不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>身份</th><th>用在哪里</th></tr></thead><tbody><tr><td>平台超级管理员</td><td>管理入口，管理组织和组织管理员恢复</td></tr><tr><td>组织账号</td><td>公共入口，进入工作台并开发或管理有权限的工程</td></tr><tr><td>工程用户</td><td>工程页面自己的登录和数据访问</td></tr></tbody></table><p>预览工具可以按权限辅助切换工程用户身份，便于检查数据范围；这不会改变你的组织登录，也不能代替正式运行中的用户登录验证。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>从<a href="/induframe-docs/zh/start/first-project.html">创建第一个工程</a>开始操作，或查看<a href="/induframe-docs/zh/guide/projects.html">工程管理</a>、<a href="/induframe-docs/zh/guide/workspace.html">应用开发</a>和<a href="/induframe-docs/zh/guide/preview.html">预览页面</a>。</p>',18)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
